-- ============================================================
-- Canonical concept ontology: seed and deterministic question mapping
--
-- Follows the approved ontology review. Additive and reversible; the rollback
-- at the foot drops only what this file creates and restores what it removes.
--
-- WHAT IS SEEDED: 488 concepts lifted from the title-case question labels,
-- status ACTIVE_SEED. That status is the point. It says "approved as a starting
-- vocabulary" and NOT "every concept permanently validated in every
-- pedagogical detail", which is a claim nobody has made and the schema should
-- not imply.
--
-- WHAT IS MAPPED: only questions whose subtopic is EXACTLY a concept name.
-- String equality, set-based, no inference. The remaining 439 questions, whose
-- labels are per-question descriptions rather than concept names, are left
-- unmapped on purpose and belong to a later reviewed pass.
--
-- WHAT IS NOT DONE: no flashcard is mapped. No descriptor question is mapped.
-- No merge from the merge report is applied, because those needed a human eye
-- and got approval for the vocabulary, not for the merges. No concept
-- relationship is created: relationships must be argued for individually.
--
-- NO evidence_floor COLUMN. It was proposed and then withdrawn on review, and
-- the reasoning is worth keeping: evidence sufficiency is a property of a
-- LEARNER'S observations, not of a concept's identity. A concept with one
-- question today may have twenty next month. Question coverage is already
-- derivable from question_concepts at query time, so storing a threshold on
-- the concept would freeze a temporary fact as if it were pedagogy.
-- split_candidate is kept, because that IS a property of the concept: the
-- label genuinely joins several objectives, whatever any learner does.
-- ============================================================

-- ────────────────────────────────────────────────────────────
-- 1. Extend `concepts`
-- ────────────────────────────────────────────────────────────

-- Empty, and superseded by the many-to-many join. Verified zero rows before
-- writing this, so the drop cannot lose data.
ALTER TABLE public.concepts DROP COLUMN IF EXISTS discipline_code;

ALTER TABLE public.concepts
  ADD COLUMN IF NOT EXISTS section_code      TEXT REFERENCES public.mcat_sections(code),
  ADD COLUMN IF NOT EXISTS concept_level     TEXT NOT NULL DEFAULT 'CONCEPT',
  ADD COLUMN IF NOT EXISTS parent_concept_id UUID REFERENCES public.concepts(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS deprecated_by     UUID REFERENCES public.concepts(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS split_candidate   BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS updated_at        TIMESTAMPTZ NOT NULL DEFAULT now();

COMMENT ON COLUMN public.concepts.section_code IS
  'Stored rather than derived from discipline, because a PSYCH_SOC concept may have a certain section and no resolved discipline at all.';
COMMENT ON COLUMN public.concepts.split_candidate IS
  'The label joins several learning objectives. Deliberately NOT split during seeding: evidence density is worth more today than precision, and a concept carrying 10 questions serves the learner model better than two carrying 5. Flagged so the decision can be revisited when diagnostic need, question volume or flashcard mapping justifies it.';
COMMENT ON COLUMN public.concepts.deprecated_by IS
  'On merge, points at the surviving concept so historical mappings resolve forward instead of dangling. IDs are never reused.';

ALTER TABLE public.concepts DROP CONSTRAINT IF EXISTS concepts_level_check;
ALTER TABLE public.concepts ADD CONSTRAINT concepts_level_check
  CHECK (concept_level IN ('CONCEPT','SUBCONCEPT'));

-- ACTIVE_SEED joins the lifecycle: approved as a starting point, versionable,
-- and distinct from a concept a human has validated in detail.
ALTER TABLE public.concepts DROP CONSTRAINT IF EXISTS concepts_status_check;
ALTER TABLE public.concepts ADD CONSTRAINT concepts_status_check
  CHECK (status IN ('DRAFT','ACTIVE_SEED','APPROVED','HUMAN_VALIDATED','NEEDS_REVIEW','DEPRECATED'));

-- A deprecated concept must say what replaced it, unless it was simply retired.
ALTER TABLE public.concepts DROP CONSTRAINT IF EXISTS concepts_deprecated_not_self;
ALTER TABLE public.concepts ADD CONSTRAINT concepts_deprecated_not_self
  CHECK (deprecated_by IS NULL OR deprecated_by <> id);

-- The join used by the deterministic mapping below has to be unambiguous.
CREATE UNIQUE INDEX IF NOT EXISTS concepts_canonical_name_key ON public.concepts(canonical_name);
CREATE INDEX IF NOT EXISTS concepts_parent_idx ON public.concepts(parent_concept_id);
CREATE INDEX IF NOT EXISTS concepts_status_idx ON public.concepts(status);

-- ────────────────────────────────────────────────────────────
-- 2. Many-to-many discipline and content category
--
-- A single column cannot express a concept that is genuinely biochemistry AND
-- general chemistry, and forcing one parent would misfile real science. Equally
-- important: a concept may have NO discipline row. A PSYCH_SOC concept whose
-- psychology/sociology split is unresolved is a valid, shippable state, and
-- absence here must never be auto-filled.
-- ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.concept_disciplines (
  concept_id      UUID NOT NULL REFERENCES public.concepts(id) ON DELETE CASCADE,
  discipline_code TEXT NOT NULL REFERENCES public.disciplines(code),
  role            TEXT NOT NULL DEFAULT 'PRIMARY' CHECK (role IN ('PRIMARY','SECONDARY')),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (concept_id, discipline_code)
);
COMMENT ON TABLE public.concept_disciplines IS
  'Which disciplines a concept belongs to. Zero rows is valid and means UNRESOLVED, never "none".';
CREATE UNIQUE INDEX IF NOT EXISTS concept_disciplines_one_primary
  ON public.concept_disciplines(concept_id) WHERE role = 'PRIMARY';

CREATE TABLE IF NOT EXISTS public.concept_content_categories (
  concept_id       UUID NOT NULL REFERENCES public.concepts(id) ON DELETE CASCADE,
  content_category TEXT NOT NULL,
  is_primary       BOOLEAN NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (concept_id, content_category)
);
CREATE UNIQUE INDEX IF NOT EXISTS concept_content_categories_one_primary
  ON public.concept_content_categories(concept_id) WHERE is_primary;

-- ────────────────────────────────────────────────────────────
-- 3. Concept relationships. Three types, each with a named consumer.
--
-- Seeded EMPTY. Relationships are claims about pedagogy and must be argued for
-- one at a time; generating them from textual similarity would fill this table
-- with thousands of assertions nobody made.
--
-- The CHECK is written so a fourth type can be added by widening it in a later
-- migration. RELATED_TO and OVERLAPS_WITH are declined for now because neither
-- has a consumer, and a relationship nothing reads becomes a dumping ground.
-- ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.concept_relationships (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  from_concept  UUID NOT NULL REFERENCES public.concepts(id) ON DELETE CASCADE,
  to_concept    UUID NOT NULL REFERENCES public.concepts(id) ON DELETE CASCADE,
  relation      TEXT NOT NULL CHECK (relation IN (
                  'PARENT_OF',              -- roll-up analytics and hierarchy
                  'COMMONLY_CONFUSED_WITH', -- Error Fingerprint and remediation
                  'PREREQUISITE_OF')),      -- study-plan recommendation engine
  status        TEXT NOT NULL DEFAULT 'AI_PROPOSED'
                  CHECK (status IN ('AI_PROPOSED','HUMAN_VALIDATED','NEEDS_REVIEW')),
  source        TEXT NOT NULL DEFAULT 'HUMAN_REVIEWED'
                  CHECK (source IN ('LEGACY_EXACT','DETERMINISTIC','AI_PROPOSED','HUMAN_REVIEWED')),
  note          TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (from_concept, to_concept, relation),
  CONSTRAINT concept_relationships_no_self CHECK (from_concept <> to_concept)
);

-- ────────────────────────────────────────────────────────────
-- 4. Structural guards
-- ────────────────────────────────────────────────────────────

-- Shallow on purpose: CONCEPT -> SUBCONCEPT and no further. A deeper tree makes
-- roll-up analytics ambiguous and has no use case yet.
CREATE OR REPLACE FUNCTION public.check_concept_hierarchy()
RETURNS TRIGGER AS $$
DECLARE parent_level TEXT; parent_parent UUID;
BEGIN
  IF NEW.parent_concept_id IS NULL THEN RETURN NEW; END IF;

  IF NEW.parent_concept_id = NEW.id THEN
    RAISE EXCEPTION 'A concept cannot be its own parent.';
  END IF;

  SELECT concept_level, parent_concept_id INTO parent_level, parent_parent
    FROM public.concepts WHERE id = NEW.parent_concept_id;

  IF parent_parent IS NOT NULL THEN
    RAISE EXCEPTION 'Concept hierarchy is limited to two levels; % already has a parent.', NEW.parent_concept_id;
  END IF;

  IF NEW.concept_level <> 'SUBCONCEPT' THEN
    RAISE EXCEPTION 'A concept with a parent must have concept_level SUBCONCEPT.';
  END IF;

  RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS concepts_hierarchy_guard ON public.concepts;
CREATE TRIGGER concepts_hierarchy_guard
  BEFORE INSERT OR UPDATE OF parent_concept_id, concept_level ON public.concepts
  FOR EACH ROW EXECUTE FUNCTION public.check_concept_hierarchy();

-- A deprecated concept accepts no NEW mappings. Existing ones survive, because
-- historical learner evidence must stay interpretable after a merge.
CREATE OR REPLACE FUNCTION public.reject_deprecated_concept_mapping()
RETURNS TRIGGER AS $$
DECLARE s TEXT;
BEGIN
  SELECT status INTO s FROM public.concepts WHERE id = NEW.concept_id;
  IF s = 'DEPRECATED' THEN
    RAISE EXCEPTION 'Concept % is DEPRECATED and cannot take new mappings. Map to its successor instead.', NEW.concept_id;
  END IF;
  RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS question_concepts_no_deprecated ON public.question_concepts;
CREATE TRIGGER question_concepts_no_deprecated
  BEFORE INSERT ON public.question_concepts
  FOR EACH ROW EXECUTE FUNCTION public.reject_deprecated_concept_mapping();

DROP TRIGGER IF EXISTS flashcard_concepts_no_deprecated ON public.flashcard_concepts;
CREATE TRIGGER flashcard_concepts_no_deprecated
  BEFORE INSERT ON public.flashcard_concepts
  FOR EACH ROW EXECUTE FUNCTION public.reject_deprecated_concept_mapping();

-- A rename keeps the ID and files the old name as an alias, so nothing that
-- referenced the concept by its previous name is silently orphaned.
CREATE OR REPLACE FUNCTION public.archive_renamed_concept()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.canonical_name IS DISTINCT FROM OLD.canonical_name THEN
    VALUES (OLD.id, OLD.canonical_name, 'LEGACY_NAME', 'DETERMINISTIC', 'HUMAN_VALIDATED')
    ON CONFLICT (alias, alias_type) DO NOTHING;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS concepts_archive_rename ON public.concepts;
CREATE TRIGGER concepts_archive_rename
  BEFORE UPDATE OF canonical_name ON public.concepts
  FOR EACH ROW EXECUTE FUNCTION public.archive_renamed_concept();

-- ────────────────────────────────────────────────────────────
-- 5. Widen mapping provenance for a deterministic pass
--
-- These mappings come from neither an AI nor a human reviewer: they are exact
-- string equality against an approved vocabulary. Calling them AI_PROPOSED
-- would overstate the doubt; calling them HUMAN_VALIDATED would overstate the
-- scrutiny, and would wrongly engage the trigger that protects human decisions.
-- ────────────────────────────────────────────────────────────
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['question_concepts','flashcard_concepts'] LOOP
    EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', t, t||'_source_check');
    EXECUTE format($f$ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (source IN
      ('LEGACY_EXACT','DETERMINISTIC','DETERMINISTIC_EXACT','AI_PROPOSED','HUMAN_REVIEWED'))$f$, t, t||'_source_check');
    EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', t, t||'_mapping_status_check');
    EXECUTE format($f$ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (mapping_status IN
      ('AI_PROPOSED','DETERMINISTIC','HUMAN_VALIDATED','NEEDS_REVIEW'))$f$, t, t||'_mapping_status_check');
  END LOOP;
END $$;

-- ────────────────────────────────────────────────────────────
-- 6. RLS for the new tables, matching the reference-data pattern
-- ────────────────────────────────────────────────────────────
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['concept_disciplines','concept_content_categories','concept_relationships'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS "read taxonomy" ON public.%I', t);
    EXECUTE format('CREATE POLICY "read taxonomy" ON public.%I FOR SELECT USING (auth.role() = ''authenticated'')', t);
  END LOOP;
END $$;

-- ────────────────────────────────────────────────────────────
-- 7. Seed the approved vocabulary
-- ────────────────────────────────────────────────────────────
-- 488 approved seed concepts.
ON CONFLICT (slug) DO NOTHING;

-- Discipline relationships. PRIMARY only: no seed label appears under more than one
-- discipline in the bank, so there is no evidence for a SECONDARY row and none is invented.
ON CONFLICT (concept_id, discipline_code) DO NOTHING;

-- Content-category relationships (491 rows; 3 concepts carry more than one).
ON CONFLICT (concept_id, content_category) DO NOTHING;
-- ────────────────────────────────────────────────────────────
-- 8. Deterministic question mapping
--
-- Set-based and exact: a question maps when its subtopic IS a concept's
-- canonical name, character for character. No normalisation, no similarity, no
-- AI. Questions whose subtopic is a per-question description match nothing and
-- are left unmapped, which is the intended outcome for this phase.
-- ────────────────────────────────────────────────────────────
SELECT q.id, c.id, 'PRIMARY', 1.00, 'DETERMINISTIC', 'DETERMINISTIC_EXACT'
FROM public.questions q
JOIN public.concepts c ON c.canonical_name = q.subtopic
WHERE c.status <> 'DEPRECATED'
ON CONFLICT (question_id, concept_id) DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- 9. Verification
-- ────────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.concepts)                      AS concepts,            -- 488
  (SELECT count(*) FROM public.concepts WHERE split_candidate) AS split_candidates,   -- 200
  (SELECT count(*) FROM public.concept_disciplines)           AS discipline_rows,     -- 488
  (SELECT count(*) FROM public.concept_content_categories)    AS category_rows,       -- 491
  (SELECT count(*) FROM public.concept_relationships)         AS relationships,       -- 0, on purpose
  (SELECT count(*) FROM public.question_concepts)             AS question_mappings,   -- 2242
  (SELECT count(*) FROM public.flashcard_concepts)            AS flashcard_mappings,  -- 0, on purpose
  (SELECT count(*) FROM public.questions)                     AS questions_intact,    -- 2681
  (SELECT count(*) FROM public.flashcards)                    AS cards_intact;        -- 4117

-- Section compatibility: a mapping whose question section differs from its
-- concept's section. Expect zero rows.
SELECT 'section mismatch' AS problem, count(*) AS n
FROM public.question_concepts qc
JOIN public.questions q ON q.id = qc.question_id
JOIN public.concepts  c ON c.id = qc.concept_id
JOIN public.legacy_taxonomy_map m
  ON m.source_system='questions' AND m.source_field='section' AND m.source_value=q.section
WHERE c.section_code IS DISTINCT FROM m.section_code;

-- Content-category compatibility. Expect zero rows.
SELECT 'category mismatch' AS problem, count(*) AS n
FROM public.question_concepts qc
JOIN public.questions q ON q.id = qc.question_id
LEFT JOIN public.concept_content_categories cc
  ON cc.concept_id = qc.concept_id AND cc.content_category = q.content_category
WHERE cc.concept_id IS NULL;

-- Exactly one PRIMARY per mapped question. Expect zero rows.
SELECT 'duplicate primary' AS problem, question_id, count(*)
FROM public.question_concepts WHERE role='PRIMARY'
GROUP BY question_id HAVING count(*) > 1;

-- Largest concepts, to spot a catch-all forming.
SELECT c.canonical_name, count(*) AS questions
FROM public.question_concepts qc JOIN public.concepts c ON c.id=qc.concept_id
GROUP BY c.canonical_name ORDER BY count(*) DESC LIMIT 8;

